#include <iostream>
#include <vector>
#include <algorithm>

class Vector {
private:
	std::vector<int> data;

public:
	void add(int value) {
		data.push_back(value);
	}

	void sort() {
		std::sort(data.begin(), data.end());
	}

	void print() {
		for (int val : data) {
			std::cout << val << " ";
		}
		std::cout << std::endl;
	}
};

#include <iostream>

template<typename T>
T findMax(T a, T b, T c) {
	T max = a;
	if (b > max) max = b;
	if (c > max) max = c;
	return max;
}

int main() {
	int maxInt = findMax(10, 20, 15);
	double maxDouble = findMax(3.14, 2.71, 1.41);

	std::cout << "Max int: " << maxInt << std::endl;
	std::cout << "Max double: " << maxDouble << std::endl;
	return 0;
}

#include <iostream>

struct Node {
	int data;
	Node* next;

	Node(int value) : data(value), next(nullptr) {}
};

class LinkedList {
private:
	Node* head;

public:
	LinkedList() : head(nullptr) {}

	void insert(int value) {
		Node* newNode = new Node(value);
		newNode->next = head;
		head = newNode;
	}

	void display() {
		Node* current = head;
		while (current) {
			std::cout << current->data << " ";
			current = current->next;
		}
		std::cout << std::endl;
	}
};
